import { daysBetween } from './dates.js';
import { balanceDue } from './payments.js';
import { roundCents } from './money.js';

/**
 * Get invoices that are overdue as of a given date.
 * @param {Array} invoices
 * @param {string} asOf - YYYY-MM-DD date
 * @returns {Array} array of { number, customerId, dueDate, daysOverdue, due }
 */
export function overdueInvoices(invoices, asOf) {
  return invoices
    .filter(inv =>
      (inv.status === 'issued' || inv.status === 'partially_paid') &&
      inv.dueDate < asOf
    )
    .map(inv => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);
}

/**
 * Get VAT summary aggregated by rate.
 * @param {Array} invoices
 * @returns {Array} array of { rate, base, vat }
 */
export function vatSummary(invoices) {
  const vatMap = {};

  for (const invoice of invoices) {
    if (invoice.status === 'draft') continue;

    for (const line of invoice.lines) {
      const lineamt = line.qty * line.unitPrice;
      const lineDiscount = lineamt * (line.discountPercent ?? 0) / 100;
      const roundedLineDiscount = roundCents(lineDiscount);
      const lineAmountAfterDiscount = lineamt - roundedLineDiscount;

      const lineVat = lineAmountAfterDiscount * (line.vatRate ?? 0) / 100;
      const roundedLineVat = roundCents(lineVat);

      const rate = line.vatRate ?? 0;
      if (!vatMap[rate]) {
        vatMap[rate] = { base: 0, vat: 0 };
      }
      vatMap[rate].base += lineAmountAfterDiscount;
      vatMap[rate].vat += roundedLineVat;
    }
  }

  return Object.entries(vatMap)
    .map(([rate, { base, vat }]) => ({
      rate: parseInt(rate, 10),
      base,
      vat,
    }))
    .sort((a, b) => b.rate - a.rate);
}

/**
 * Calculate late fee for an invoice.
 * 0.04% of the amount due for each day overdue.
 * @param {{ dueDate: string, payments?: Array, lines: Array }} invoice
 * @param {string} asOf - YYYY-MM-DD date
 * @returns {number} late fee in cents
 */
export function lateFee(invoice, asOf) {
  if (invoice.dueDate >= asOf) {
    return 0;
  }

  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  const amountDue = balanceDue(invoice);

  const fee = amountDue * 0.0004 * daysOverdue;
  return roundCents(fee);
}

